{"file_text": "namespace MyApp.Evals.Tests;

/// <summary>
/// Custom evaluator: counts whitespace-separated words in the response.
/// Provides a basic sanity check that the model produced output of reasonable length.
/// </summary>
internal sealed class WordCountEvaluator : IEvaluator
{
    public string Name => "Words";

    public IReadOnlyList<string> Metrics => ["Words"];

    public Task<EvaluationResult> EvaluateAsync(
        IEnumerable<ChatMessage> messages,
        ChatResponse response,
        IEnumerable<EvaluationContext>? additionalContext = null,
        CancellationToken cancellationToken = default)
    {
        var text = response.Text ?? string.Empty;
        var count = text.Split((char[]?)null, StringSplitOptions.RemoveEmptyEntries).Length;

        var result = new EvaluationResult();
        var metric = new NumericMetric("Words", count);

        if (count < 5)
            metric.AddDiagnostic(EvaluationDiagnostic.Warning("Response very short (< 5 words)"));
        else if (count > 500)
            metric.AddDiagnostic(EvaluationDiagnostic.Informational("Response unusually long (> 500 words)"));

        result.Metrics.Add("Words", metric);
        return Task.FromResult(result);
    }
}
