internal static class Thresholds
{
    public static void ApplyOrLog(EvaluationResult result, string scenarioId)
    {
        // Thresholds are advisory by default. Edit quality.thresholds.json
        // and set hard_fail: true to enforce.
        foreach (var (name, metric) in result.Metrics)
        {
            if (metric.Diagnostics.Any(d => d.Severity == EvaluationDiagnosticSeverity.Error))
            {
                Console.WriteLine($"[WARN] {scenarioId}/{name}: metric error reported");
            }
        }
    }
}

