using System.Diagnostics;
using System.Text.Json;

namespace MyApp.Evals.Tests;

[TestClass]
public sealed class TelemetryTests
{
    public static IEnumerable<object[]> Inputs() =>
        InputsLoader.Load().Select(i => new object[] { i });

    [TestMethod]
    [DynamicData(nameof(Inputs), DynamicDataSourceType.Method)]
    public async Task Capture(TelemetryInput input)
    {
        var inner = Wire.ResolveAgentClient();
        var prices = PriceTable.Load();

        var messages = new List<ChatMessage> { new(ChatRole.User, input.Text) };
        var sw = Stopwatch.StartNew();
        var response = await inner.GetResponseAsync(messages);
        sw.Stop();

        var usage = response.Usage;
        var inputTokens = usage?.InputTokenCount ?? 0;
        var outputTokens = usage?.OutputTokenCount ?? 0;
        var cost = prices.Cost(response.ModelId ?? "unknown", inputTokens, outputTokens);

        TelemetryStore.Record(new TelemetryRecord(
            Agent: input.Agent,
            Model: response.ModelId ?? "unknown",
            InputTokens: inputTokens,
            OutputTokens: outputTokens,
            LatencyMs: sw.ElapsedMilliseconds,
            CostUsd: cost));
    }

    [ClassCleanup]
    public static void WriteReports() => TelemetryStore.FlushTo(
        Path.Combine(RepoRoot.Find(), ".copilot", "perf-reports", "evals", EvalEnv.ReportFolder));
}

internal sealed record TelemetryInput
{
    public string Agent { get; init; } = "";
    public string Text { get; init; } = "";

    public override string ToString() => $"{Agent}: {Text[..Math.Min(30, Text.Length)]}";
}

internal static class InputsLoader
{
    private static readonly JsonSerializerOptions s_options = new()
    {
        PropertyNamingPolicy = JsonNamingPolicy.SnakeCaseLower,
        PropertyNameCaseInsensitive = true,
    };

    public static List<TelemetryInput> Load()
    {
        var path = Path.Combine(AppContext.BaseDirectory, "Telemetry", "inputs.json");
        return JsonSerializer.Deserialize<List<TelemetryInput>>(
            File.ReadAllText(path), s_options) ?? new();
    }
}

internal sealed record TelemetryRecord(
    string Agent, string Model, int InputTokens, int OutputTokens,
    long LatencyMs, decimal CostUsd);

internal static class TelemetryStore
{
    private static readonly List<TelemetryRecord> s_records = new();

    public static void Record(TelemetryRecord r)
    {
        lock (s_records) s_records.Add(r);
    }

    public static void FlushTo(string outDir)
    {
        Directory.CreateDirectory(outDir);
        List<TelemetryRecord> snapshot;
        lock (s_records) snapshot = s_records.ToList();

        // telemetry.json
        var json = JsonSerializer.Serialize(snapshot, new JsonSerializerOptions { WriteIndented = true });
        File.WriteAllText(Path.Combine(outDir, "telemetry.json"), json);

        // telemetry.md
        var md = new System.Text.StringBuilder();
        md.AppendLine("# Telemetry capture");
        md.AppendLine();
        md.AppendLine("| Agent | Model | Input tokens | Output tokens | Latency (ms) | Cost (USD) |");
        md.AppendLine("|-------|-------|-------------|--------------|-------------|-----------|");
        foreach (var r in snapshot)
            md.AppendLine($"| {r.Agent} | {r.Model} | {r.InputTokens} | {r.OutputTokens} | {r.LatencyMs} | ${r.CostUsd:F6} |");
        File.WriteAllText(Path.Combine(outDir, "telemetry.md"), md.ToString());

        Console.WriteLine($"[Telemetry] {outDir}/telemetry.md ({snapshot.Count} records)");
    }
}

