using OpenAI;

namespace MyApp.Evals.Tests;

internal static class AgentChatClientFactory
{
    /// <summary>
    /// Resolves the same IChatClient the app uses, by building from configuration.
    /// Detected: AddAzureOpenAIChatClient("chat", "gpt-4o-mini") at AppHost.cs:1
    /// </summary>
    public static IChatClient Create()
    {
        var builder = Host.CreateApplicationBuilder();

        // In test hosts (dotnet test), the entry assembly is testhost.exe so
        // user-secrets are NOT auto-loaded by CreateApplicationBuilder.
        builder.Configuration.AddUserSecrets(typeof(AgentChatClientFactory).Assembly, optional: true);
        var host = builder.Build();

        var connStr = host.Services.GetRequiredService<IConfiguration>()
            .GetConnectionString("chat");

        if (string.IsNullOrEmpty(connStr))
        {
            throw new InvalidOperationException(
                "EVAL_USE_REAL_AGENT=1 but ConnectionStrings:chat is not configured. " +
                "Aspire's AppHost populates this at runtime, but `dotnet test` runs standalone. Wire one of:\n" +
                "  dotnet user-secrets init --project MyApp.Evals.Tests\n" +
                "  # Key-based auth (only if the resource has it enabled):\n" +
                "  dotnet user-secrets set \"ConnectionStrings:chat\" " +
                "\"Endpoint=https://<host>.services.ai.azure.com/models;Key=<key>;DeploymentId=chat\" --project MyApp.Evals.Tests\n" +
                "  # Entra-ID auth (DefaultAzureCredential — works when key auth is disabled):\n" +
                "  dotnet user-secrets set \"ConnectionStrings:chat\" " +
                "\"Endpoint=https://<host>.services.ai.azure.com/models;DeploymentId=chat\" --project MyApp.Evals.Tests\n" +
                "Note: the hostname strips dashes from the resource name " +
                "(resource `foundry-abc` -> host `foundryabc.services.ai.azure.com`).");
        }

        return CreateFromConnectionString(connStr);
    }

    private static IChatClient CreateFromConnectionString(string connStr)
    {
        var parts = connStr.Split(';')
            .Select(p => p.Split('=', 2))
            .Where(p => p.Length == 2)
            .ToDictionary(p => p[0].Trim(), p => p[1].Trim(), StringComparer.OrdinalIgnoreCase);

        parts.TryGetValue("Endpoint", out var endpoint);
        parts.TryGetValue("Key", out var key);
        parts.TryGetValue("DeploymentId", out var deploymentId);

        if (string.IsNullOrEmpty(endpoint))
            throw new InvalidOperationException("ConnectionStrings:chat must contain an Endpoint= segment.");

        OpenAIClient client;
        if (!string.IsNullOrEmpty(key))
            client = new AzureOpenAIClient(new Uri(endpoint), new ApiKeyCredential(key));
        else
            client = new AzureOpenAIClient(new Uri(endpoint), new Azure.Identity.DefaultAzureCredential());

        return client.GetChatClient(deploymentId ?? "chat").AsIChatClient();
    }
}

