public static IChatClient ResolveJudgeClient(IChatClient agentClient)
{
    var judgeDeployment = Environment.GetEnvironmentVariable("EVAL_JUDGE_DEPLOYMENT_NAME");
    if (!string.IsNullOrEmpty(judgeDeployment))
    {
        // Override: resolve a separate client for the judge deployment
        var builder = Host.CreateApplicationBuilder();
        builder.Configuration.AddUserSecrets(typeof(AgentChatClientFactory).Assembly, optional: true);
        var host = builder.Build();
        var connStr = host.Services.GetRequiredService<IConfiguration>()
            .GetConnectionString(judgeDeployment)
            ?? host.Services.GetRequiredService<IConfiguration>()
                .GetConnectionString("chat");

        if (string.IsNullOrEmpty(connStr))
            throw new InvalidOperationException(
                $"EVAL_JUDGE_DEPLOYMENT_NAME={judgeDeployment} but no matching ConnectionStrings entry found.");

        // Reuse the same connection-string parsing as the agent factory
        return AgentChatClientFactory.Create();
    }
    return agentClient;
}

